import{_ as e,c as r,o as t,a2 as i}from"./chunks/framework.CzULAunO.js";const c=JSON.parse('{"title":"网络空间安全—密码管理 Part1","description":"","frontmatter":{},"headers":[],"relativePath":"docs/general-skills/cyber security/password_manage1.md","filePath":"docs/general-skills/cyber security/password_manage1.md","lastUpdated":1766652908000}'),l={name:"docs/general-skills/cyber security/password_manage1.md"};function o(s,a,n,d,h,p){return t(),r("div",null,a[0]||(a[0]=[i('<h1 id="网络空间安全—密码管理-part1" tabindex="-1"><strong>网络空间安全—密码管理 Part1</strong> <a class="header-anchor" href="#网络空间安全—密码管理-part1" aria-label="Permalink to &quot;**网络空间安全—密码管理 Part1**&quot;">​</a></h1><h2 id="part1-更新状态-✅" tabindex="-1">part1 更新状态：✅ <a class="header-anchor" href="#part1-更新状态-✅" aria-label="Permalink to &quot;part1 更新状态：✅&quot;">​</a></h2><h2 id="part2-❌" tabindex="-1">part2：❌ <a class="header-anchor" href="#part2-❌" aria-label="Permalink to &quot;part2：❌&quot;">​</a></h2><h2 id="part3-❌" tabindex="-1">part3：❌ <a class="header-anchor" href="#part3-❌" aria-label="Permalink to &quot;part3：❌&quot;">​</a></h2><ul><li>随着网络空间安全危害事件的发生，密码作为个人信息账号的第一道防线，应该得到重视。</li><li>很多人都有这个经历： <blockquote><ul><li><a href="https://linux.do/t/topic/235317" target="_blank" rel="noreferrer">https://linux.do/t/topic/235317</a></li><li><a href="https://linux.do/t/topic/239657" target="_blank" rel="noreferrer">https://linux.do/t/topic/239657</a></li><li><a href="https://linux.do/t/topic/235505" target="_blank" rel="noreferrer">https://linux.do/t/topic/235505</a></li></ul></blockquote></li><li>如果你频繁使用一个账户密码，且缺少二次验证，攻击者可以使用撞库等手段，破解你几乎所有的账号。</li><li>下面，以 Android 为主，MacOS 为辅，通过各种手段，加强账号信息强度：</li></ul><h2 id="检查密码强度" tabindex="-1">检查密码强度 <a class="header-anchor" href="#检查密码强度" aria-label="Permalink to &quot;检查密码强度&quot;">​</a></h2><blockquote><ol><li>你是不是经常在各大网站使用同一个密码？</li><li>你的密码是不是和个人姓名，生日等等息息相关？</li><li>你的密码是不是只存储在浏览器里？</li></ol></blockquote><h3 id="开源密码强度检测软件" tabindex="-1">开源密码强度检测软件 <a class="header-anchor" href="#开源密码强度检测软件" aria-label="Permalink to &quot;开源密码强度检测软件&quot;">​</a></h3><p><img src="https://f-droid.org/repo/com.cyb3rko.pazzword/en-US/icon_4TlGVCx28WCvT9UWJJd3LIJnGxbG0XnQgrMEhJKROYc=.png" alt="img"></p><p><strong>Pazzword</strong></p><p><a href="https://github.com/cyb3rko/pazzword" target="_blank" rel="noreferrer"><strong>Github</strong></a></p><p><a href="https://f-droid.org/zh_Hant/packages/com.cyb3rko.pazzword/index.html" target="_blank" rel="noreferrer"><strong>F-Droid</strong></a></p><p><a href="https://play.google.com/store/apps/details?id=com.cyb3rko.pazzword&amp;hl=zh" target="_blank" rel="noreferrer"><strong>G-Play</strong></a></p><p>输入你常用的 (不放心可以输修改后的) 密码，</p><h3 id="可以得到诸如" tabindex="-1">可以得到诸如 <a class="header-anchor" href="#可以得到诸如" aria-label="Permalink to &quot;可以得到诸如&quot;">​</a></h3><blockquote><ol><li>密码是否安全</li><li>密码是否常见</li><li>加密指数</li><li>修改建议</li><li>是否含有字典关键词</li><li>破解猜测次数，时长</li></ol></blockquote><p>比如密码：<strong>neoisgreat</strong></p><blockquote><ul><li>Guesses：1.69X10^8</li><li>Offline MD5：瞬间</li><li>Offline SHA512：瞬间</li><li>Offline bcrypt10:7min</li><li>Offline bcrypt14:1h</li><li>Online Unthrottled：3days</li><li>Online Throttled：2 years 同时配备强密码生成器，但不推荐，因为有更好的方法，生成管理强密码；</li></ul></blockquote><h3 id="强大的开源密码管理器" tabindex="-1">强大的开源密码管理器 <a class="header-anchor" href="#强大的开源密码管理器" aria-label="Permalink to &quot;强大的开源密码管理器&quot;">​</a></h3><h4 id="keepass-windows-linux" tabindex="-1"><a href="https://keepass.info/" target="_blank" rel="noreferrer">KeePass</a>（Windows/Linux） <a class="header-anchor" href="#keepass-windows-linux" aria-label="Permalink to &quot;[KeePass](https://keepass.info/)（Windows/Linux）&quot;">​</a></h4><p>可以说这个软件是最古老和最初的根源，现在几乎绝大多数的开源密码管理器都是在他的基础上二次修改得到的，它至今还在活跃地进行更新</p><p>支持以下众多特性：</p><ul><li>WebDAV</li><li>密码生成</li><li>密码强度检测</li><li>自动填充（基于插件与扩展，有多种不同技术路线可选，推荐 <a href="https://keepass.info/plugins.html#keepasshttp" target="_blank" rel="noreferrer">KeePassHttp</a> 与其相关插件）</li><li>OTP（2FA，基于插件 <a href="https://keepass.info/plugins.html#keeotp" target="_blank" rel="noreferrer">KeeOtp2</a>）</li><li>增加附件</li><li>等</li></ul><h4 id="keepass2android-android" tabindex="-1"><a href="https://github.com/PhilippC/keepass2android" target="_blank" rel="noreferrer">KeePass2Android</a>（Android） <a class="header-anchor" href="#keepass2android-android" aria-label="Permalink to &quot;[KeePass2Android](https://github.com/PhilippC/keepass2android)（Android）&quot;">​</a></h4><p>安卓目前下载量最多的 KeePass 系列软件，原生支持 WebDAV、OTP（2FA）、附件、自动填充等功能，基本上 KeePass 的基本功能他都有</p><p>有两个版本，一个支持联网（可以与 WebDAV 等功能联动），一个仅使用本地数据（保护隐私），可以看情况下载</p><h4 id="keepassdx-windows-linux-android" tabindex="-1"><a href="https://github.com/Kunzisoft/KeePassDX" target="_blank" rel="noreferrer">KeePassDX</a>（Windows/Linux/Android） <a class="header-anchor" href="#keepassdx-windows-linux-android" aria-label="Permalink to &quot;[KeePassDX](https://github.com/Kunzisoft/KeePassDX)（Windows/Linux/Android）&quot;">​</a></h4><p><a href="https://f-droid.org/packages/com.kunzisoft.keepass.libre/" target="_blank" rel="noreferrer">F-Droid</a>｜<a href="https://play.google.com/store/apps/details?id=com.kunzisoft.keepass.free" target="_blank" rel="noreferrer">G-Play</a>｜<a href="https://github.com/Kunzisoft/KeePassDX/releases" target="_blank" rel="noreferrer">Github</a></p><h5 id="优点" tabindex="-1">优点 <a class="header-anchor" href="#优点" aria-label="Permalink to &quot;优点&quot;">​</a></h5><ul><li>安全性高 <ul><li>数据不存储在云端，而是在本地仓库<img src="https://ooo.0x0.ooo/2024/10/26/OD8znB.png" alt="OD8znB.png"></li><li>自主选择加密方式，任意搭配开启关闭<strong>密码登陆，指纹解锁，密钥文件，实物密钥</strong> (密钥文件可在 termux 生成) <img src="https://ooo.0x0.ooo/2024/10/26/OD8F4s.png" alt="OD8F4s.png"></li></ul></li><li>定制化程度高 <ul><li>作为赛博人，软件安全性固然重要，但我们也不想使用一款难看的老式 UI 软件，KeePassDX 提供内置图标和自定义图标，让密码管理也能乐在其中。 <img src="https://ooo.0x0.ooo/2024/10/26/OD87YN.png" alt="OD87YN.png"></li></ul></li><li>迁移能力强 <ul><li>由于密码都存储在一个文件里 (当然你也可以搭建更多个数据库存储不同密码)，我们迁移密码只需要将密码数据库和密钥文件移动到目的地，搭配不同平台不同软件都可以直接使用 (图标包会存储在.kdbx 文件)</li><li>比如我在 Android 端，将文件，密钥迁移到 MacOS，只需要下载 MacPass 或者 KeePassXC 等开源软件，导入数据即可使用。</li><li>使用 resillion sync 或 syncthing 可以高效的同步密码库，多端同步</li></ul></li></ul><h5 id="缺点" tabindex="-1">缺点 <a class="header-anchor" href="#缺点" aria-label="Permalink to &quot;缺点&quot;">​</a></h5><ul><li>ALL IN BOOM <ul><li>正因为密码存储在数据库文件，如果误删密码库，要么去找文件恢复软件，要么从其他地方备份，要么......寄！</li><li>所以，要开启不同的登陆验证方式，勤备份文件到安全的地方，多端同步。</li></ul></li></ul><h4 id="bitwarden-android-windows-linux-ios-macos-web" tabindex="-1"><a href="https://bitwarden.com/" target="_blank" rel="noreferrer">Bitwarden</a>（Android/Windows/Linux/IOS/MacOS/Web） <a class="header-anchor" href="#bitwarden-android-windows-linux-ios-macos-web" aria-label="Permalink to &quot;[Bitwarden](https://bitwarden.com/)（Android/Windows/Linux/IOS/MacOS/Web）&quot;">​</a></h4><p>Bitwarden 是一个线上的开源密码管理器，你可以使用官方提供的服务，或者自己搭建一个服务器（<a href="https://www.iplaysoft.com/bitwarden-self-host.html" target="_blank" rel="noreferrer">教程见此</a>）。官方提供的功能有限制不过一般够用了，自己搭建就没什么限制了。</p><h4 id="其它" tabindex="-1">其它 <a class="header-anchor" href="#其它" aria-label="Permalink to &quot;其它&quot;">​</a></h4><p>其他付费的密码管理软件因其收费较为高昂（例如 LastPass 等），一般学生难以负担，或者过于小众因此不在此说明。</p><details><summary>关于作者</summary><blockquote><p>文章地址：</p><ul><li>Linuxdo <a href="https://linux.do/t/topic/242686" target="_blank" rel="noreferrer">https://linux.do/t/topic/242686</a></li><li>Ac-Wiki <a href="https://github.com/Ac-Wiki/Ac-Wiki/blob/main/03-tools/cyber%20security/password_manage1.md" target="_blank" rel="noreferrer">https://github.com/Ac-Wiki/Ac-Wiki/blob/main/03-tools/cyber security/password_manage1.md</a></li></ul><p>作者：</p><ul><li>user695(linux.do) <a href="https://linux.do/u/user695/summary" target="_blank" rel="noreferrer">https://linux.do/u/user695/summary</a></li><li>KipJaychou(Github) <a href="https://github.com/KipJayChou" target="_blank" rel="noreferrer">https://github.com/KipJayChou</a></li></ul><p>向我申请 Linuxdo 邀请码： <a href="mailto:jay20070220@gmail.com" target="_blank" rel="noreferrer">mailto:jay20070220@gmail.com</a></p></blockquote></details>',37)]))}const b=e(l,[["render",o]]);export{c as __pageData,b as default};
